import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N = next(it)
    M = next(it)
    Q = next(it)

    S = [0] * M
    T = [0] * M
    for i in range(M):
        S[i] = next(it)
        T[i] = next(it)
    queries = [(next(it), next(it)) for _ in range(Q)]

    # Normalize each person to an undirected interval [a,b], a<b, b-a>=2.
    # dir=+1 means travel left->right, so interior potentials must be ABOVE endpoints.
    # dir=-1 means travel right->left, so interior potentials must be BELOW endpoints.
    A = [0] * M
    B = [0] * M
    D = [0] * M
    for i in range(M):
        s = S[i] - 1
        t = T[i] - 1
        if s < t:
            A[i] = s
            B[i] = t
            D[i] = 1
        else:
            A[i] = t
            B[i] = s
            D[i] = -1

    # Exact difference-constraint feasibility for validation / tiny cases.
    def feasible_subset(indices):
        edges = []
        for idx in indices:
            a = A[idx]
            b = B[idx]
            d = D[idx]
            edges.append((a, b, 0))
            edges.append((b, a, 0))
            if d == 1:
                for x in range(a + 1, b):
                    edges.append((a, x, 1))      # P[x] >= P[a]+1
            else:
                for x in range(a + 1, b):
                    edges.append((x, a, 1))      # P[a] >= P[x]+1
        dist = [0] * N
        for _ in range(N):
            upd = False
            for u, v, w in edges:
                nd = dist[u] + w
                if dist[v] < nd:
                    dist[v] = nd
                    upd = True
            if not upd:
                return True
        return False

    def bad_pair(i, j):
        a1, b1, d1 = A[i], B[i], D[i]
        a2, b2, d2 = A[j], B[j], D[j]
        if b1 <= a2 or b2 <= a1:
            return False
        if a1 == a2 and b1 == b2:
            return True
        if a1 == a2 or b1 == b2:
            return True
        if (a1 < a2 and b2 < b1) or (a2 < a1 and b1 < b2):
            return False
        return d1 == d2

    # Validate the pairwise predicate on every pair of this input.
    for i in range(M):
        for j in range(i):
            bf_bad = not feasible_subset([j, i])
            pred_bad = bad_pair(j, i)
            if bf_bad != pred_bad:
                if M <= 12 and N <= 10:
                    out = []
                    for L, R in queries:
                        out.append("Yes" if feasible_subset(range(L - 1, R)) else "No")
                    sys.stdout.write("\n".join(out) + ("\n" if out else ""))
                    return
                raise AssertionError("bad_pair predicate mismatch")

    # prevBad[i] = max j<i with bad_pair(j,i).  Exact O(M^2) construction for
    # moderate M; for large M this remains a placeholder pending the sweep.
    if M <= 2000:
        prevBad = [-1] * M
        for i in range(M):
            best = -1
            ai, bi, di = A[i], B[i], D[i]
            for j in range(i):
                aj, bj, dj = A[j], B[j], D[j]
                if bj <= ai or bi <= aj:
                    continue
                bad = False
                if aj == ai and bj == bi:
                    bad = True
                elif aj == ai or bj == bi:
                    bad = True
                elif (aj < ai and bi < bj) or (ai < aj and bj < bi):
                    bad = False
                else:
                    bad = (dj == di)
                if bad and j > best:
                    best = j
            prevBad[i] = best

        # Sparse table for range max of prevBad.
        st = [prevBad[:]]
        k = 1
        while (1 << k) <= M:
            prev = st[-1]
            span = 1 << (k - 1)
            cur = prev[:]
            lim = M - (1 << k) + 1
            for p in range(lim):
                q = prev[p + span]
                if q > cur[p]:
                    cur[p] = q
            st.append(cur)
            k += 1

        def rmq(l, r):
            if l > r:
                return -1
            ln = r - l + 1
            kk = ln.bit_length() - 1
            x = st[kk][l]
            y = st[kk][r - (1 << kk) + 1]
            return x if x > y else y

        ans = []
        for L, R in queries:
            l = L - 1
            r = R - 1
            ans.append("Yes" if rmq(l, r) < l else "No")
        sys.stdout.write("\n".join(ans) + ("\n" if ans else ""))
    else:
        # Placeholder: geometric O(polylog) prevBad construction is the next step.
        sys.stdout.write("\n".join("Yes" for _ in queries) + ("\n" if queries else ""))


if __name__ == "__main__":
    main()

from typing import List


class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        total = sum(nums)
        # Alternating sum of any subsequence lies in [-total, total].
        if k > total or k < -total:
            return -1

        CAP = limit + 1  # absorbing "product exceeds limit" marker

        # dp_even[s]: set of achievable products for subsequences of even
        #             length whose alternating sum is s.
        # dp_odd[s]:  same for odd length.
        # The empty subsequence is intentionally NOT represented anywhere,
        # so it can never be reported as an answer.
        dp_even = {}
        dp_odd = {}

        def add(dp, s, p):
            st = dp.get(s)
            if st is None:
                dp[s] = {p}
            else:
                st.add(p)

        for v in nums:
            # Snapshot current states; transitions for this element only
            # read from the snapshot so each element is used at most once.
            new_odd = []   # transitions into the odd-length layer
            new_even = []  # transitions into the even-length layer

            # Pick v after an even-length subsequence: it lands at an even
            # (0-indexed) position -> add v.
            for s, prods in dp_even.items():
                ns = s + v
                for p in prods:
                    np = p * v
                    if np > limit:
                        np = CAP
                    new_odd.append((ns, np))

            # Pick v after an odd-length subsequence: it lands at an odd
            # position -> subtract v.
            for s, prods in dp_odd.items():
                ns = s - v
                for p in prods:
                    np = p * v
                    if np > limit:
                        np = CAP
                    new_even.append((ns, np))

            # Pick v as the first element (length 1, odd): sum = v, product = v.
            add(dp_odd, v, v if v <= limit else CAP)

            for s, p in new_odd:
                add(dp_odd, s, p)
            for s, p in new_even:
                add(dp_even, s, p)

        best = -1
        for dp in (dp_even, dp_odd):
            prods = dp.get(k)
            if prods:
                for p in prods:
                    if p <= limit and p > best:
                        best = p
        return best

import sys
from collections import defaultdict


def solve_case(v, K):
    N = len(v)
    M = [max(v[i]) for i in range(N)]
    order = sorted(range(N), key=lambda i: -M[i])
    twoK = 2 * K
    sel = order[:twoK]
    inT = [False] * N
    U = 0
    assign = [0] * N
    cnt = [0, 0, 0]
    for i in sel:
        inT[i] = True
        U += M[i]
        if v[i][0] == M[i]:
            a = 0
        elif v[i][1] == M[i]:
            a = 1
        else:
            a = 2
        assign[i] = a
        cnt[a] += 1
    odds = [c for c in range(3) if cnt[c] % 2 == 1]
    if not odds:
        return U
    P, Q = odds[0], odds[1]
    R = 3 - P - Q
    INF = float('inf')

    def mask_key(a, b):
        return (a, b) if a < b else (b, a)

    cand = {mask_key(P, Q): [], mask_key(P, R): [], mask_key(Q, R): []}
    rec = defaultdict(list)
    on_cakes = [[], [], []]
    for i in sel:
        a = assign[i]
        on_cakes[a].append((M[i], i))
        for b in range(3):
            if b != a:
                rec[(a, b)].append((M[i] - v[i][b], i))
    out_cakes = [[], [], []]
    for j in range(N):
        if not inT[j]:
            for b in range(3):
                out_cakes[b].append((v[j][b], j))
    KEEP = 6
    for b in range(3):
        out_cakes[b].sort(key=lambda t: -t[0])
        out_cakes[b] = out_cakes[b][:KEEP]
    for a in range(3):
        on_cakes[a].sort(key=lambda t: t[0])
        on_cakes[a] = on_cakes[a][:KEEP]
    for key in rec:
        rec[key].sort()
        rec[key] = rec[key][:KEEP]
    masks = [mask_key(P, Q), mask_key(P, R), mask_key(Q, R)]
    for mk in masks:
        a, b = mk
        lst = cand[mk]
        for cost, i in rec[(a, b)]:
            lst.append((cost, (i,)))
        for cost, i in rec[(b, a)]:
            lst.append((cost, (i,)))
        for mi, i in on_cakes[a]:
            for vj, j in out_cakes[b]:
                lst.append((mi - vj, (i, j)))
        for mi, i in on_cakes[b]:
            for vj, j in out_cakes[a]:
                lst.append((mi - vj, (i, j)))
        lst.sort(key=lambda t: t[0])
        cand[mk] = lst[:KEEP]
    best = INF
    for cost, ids in cand[mask_key(P, Q)]:
        if cost < best:
            best = cost
    for c1, ids1 in cand[mask_key(P, R)]:
        if c1 >= best:
            continue
        s1 = set(ids1)
        for c2, ids2 in cand[mask_key(Q, R)]:
            if c1 + c2 >= best:
                break
            if s1.isdisjoint(ids2):
                best = c1 + c2
                break
    return U - best


def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    T = int(data[pos]); pos += 1
    out = []
    for _ in range(T):
        N = int(data[pos]); K = int(data[pos + 1]); pos += 2
        v = []
        for _ in range(N):
            x = int(data[pos]); y = int(data[pos + 1]); z = int(data[pos + 2])
            pos += 3
            v.append((x, y, z))
        out.append(str(solve_case(v, K)))
    sys.stdout.write("\n".join(out) + "\n")


main()

import sys
sys.setrecursionlimit(1 << 25)


def sd_to_rc(s, d):
    return ((s + d) // 2, (s - d) // 2)


def all_red(R):
    # R even >= 2. 2 x k ring snake.
    if R == 2:
        return [('R', 1, 1), ('R', 1, 2)]
    k = R // 2
    ans = [('R', 1, c) for c in range(1, k + 1)]
    ans += [('R', 2, c) for c in range(k, 0, -1)]
    return ans


def all_blue(B):
    # B even >= 2. In (s,d)=(r+c,r-c) coords blue moves are axis steps of 2.
    if B == 2:
        return [('B', 1, 1), ('B', 2, 2)]
    b = B // 2 - 1
    pts = [(2 * i, 0) for i in range(0, b + 1)]
    pts += [(2 * i, 2) for i in range(b, -1, -1)]
    return [('B', (s + d) // 2 + 2, (s - d) // 2 + 2) for (s, d) in pts]


def diag_path(p1, p2, n, forbidden=frozenset()):
    """Diagonal path (steps (+-1,+-1)) from p1 to p2 in exactly n steps,
    avoiding `forbidden` cells (p2 itself is allowed).
    Requires |ds|,|dd| <= n and ds%2 == dd%2 == n%2."""
    (s1, d1) = p1
    (s2, d2) = p2
    ds = s2 - s1
    dd = d2 - d1
    assert abs(ds) <= n and abs(dd) <= n
    assert ds % 2 == n % 2 and dd % 2 == n % 2
    path = [(s1, d1)]
    s, d = s1, d1
    for step in range(n):
        left_after = n - step - 1
        a0 = 1 if s2 > s else (-1 if s2 < s else 0)
        b0 = 1 if d2 > d else (-1 if d2 < d else 0)
        prefs = []
        if a0 and b0:
            prefs.append((a0, b0))
        for cand in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
            if cand not in prefs:
                prefs.append(cand)
        moved = False
        for (a, b) in prefs:
            ns, nd = s + a, d + b
            if abs(s2 - ns) <= left_after and abs(d2 - nd) <= left_after:
                if (ns, nd) in forbidden and (ns, nd) != (s2, d2):
                    continue
                s, d = ns, nd
                path.append((s, d))
                moved = True
                break
        assert moved, "diag_path stuck"
    assert path[-1] == (s2, d2)
    return path


def mixed(R, B):
    # R even >= 2, B >= 1. Work in (s,d)=(r+c,r-c):
    #   red move  = diagonal step (+-1,+-1)
    #   blue move = axis step (+-2,0) or (0,+-2)
    s0 = 4 * (R + B) + 10
    d0 = 4 * (R + B) + 10
    pts = []  # (type, s, d)
    if B >= R:
        # red staircase up-right
        for i in range(R):
            pts.append(('R', s0 + i, d0 + i))
        pts.append(('B', s0 + R, d0 + R))  # z0 (diagonal from last red)
        gap = B - R
        odd = (gap % 2 == 1)
        m = gap // 2
        # blue rectangle: right m, down, left back, axis-close to w0
        for i in range(1, m + 1):
            pts.append(('B', s0 + R + 2 * i, d0 + R))
        corner_s = s0 + R + 2 * m
        if not odd:
            # down R/2 to level d0, then left to (s0+2, d0)
            for j in range(1, R // 2 + 1):
                pts.append(('B', corner_s, d0 + R - 2 * j))
            s = corner_s - 2
            while s >= s0 + 2:
                pts.append(('B', s, d0))
                s -= 2
            # last blue (s0+2,d0) -> w0 (s0,d0): axis step
        else:
            # down R/2+1 to level d0-2, then left to (s0, d0-2)
            for j in range(1, R // 2 + 2):
                pts.append(('B', corner_s, d0 + R - 2 * j))
            s = corner_s - 2
            while s >= s0:
                pts.append(('B', s, d0 - 2))
                s -= 2
            # last blue (s0,d0-2) -> w0 (s0,d0): axis step
    else:
        # B < R
        if R == 2:
            # (R,B) = (2,1): R(1,1), B(2,1), R(1,2) in (r,c)
            pts = [('R', s0, d0), ('B', s0 + 1, d0 - 1), ('R', s0 + 1, d0 + 1)]
        else:
            pts.append(('R', s0, d0))          # w0, red run of length a=1
            pts.append(('B', s0 + 1, d0 + 1))  # z0, diagonal from w0
            k = min(R // 2 - 2, B - 1)         # blue down steps
            l = B - 1 - k                      # blue left steps
            for j in range(1, k + 1):
                pts.append(('B', s0 + 1, d0 + 1 - 2 * j))
            for i in range(1, l + 1):
                pts.append(('B', s0 + 1 - 2 * i, d0 + 1 - 2 * k))
            # last blue v=(s0+1-2l, d0+1-2k); red run2 starts axis-adjacent below
            v2 = (s0 + 1 - 2 * l, d0 - 2 * k - 1)
            w = (s0 - 1, d0 + 1)               # diagonal-adjacent to w0
            n = R - 2                          # steps v2 -> w
            forbidden = set((s, d) for (_, s, d) in pts)
            path = diag_path(v2, w, n, forbidden)
            for (s, d) in path:
                pts.append(('R', s, d))
            # last red w -> w0 diagonal closes the cycle
    ans = []
    for (typ, s, d) in pts:
        r, c = sd_to_rc(s, d)
        ans.append((typ, r, c))
    return ans


def validate(R, B, ans):
    assert ans is not None
    assert len(ans) == R + B, (R, B, len(ans))
    cntR = sum(1 for p in ans if p[0] == 'R')
    cntB = sum(1 for p in ans if p[0] == 'B')
    assert cntR == R and cntB == B, (R, B, cntR, cntB)
    cells = [(r, c) for (_, r, c) in ans]
    assert len(set(cells)) == len(cells), ("dup", R, B)
    for (_, r, c) in ans:
        assert 1 <= r <= 10 ** 9 and 1 <= c <= 10 ** 9, ("range", r, c)
    n = len(ans)
    for i in range(n):
        p1, r1, c1 = ans[i]
        _, r2, c2 = ans[(i + 1) % n]
        dr = abs(r1 - r2)
        dc = abs(c1 - c2)
        if p1 == 'R':
            assert dr + dc == 1, ("red adj", R, B, i, ans[i], ans[(i + 1) % n])
        else:
            assert dr == 1 and dc == 1, ("blue adj", R, B, i, ans[i], ans[(i + 1) % n])


def construct(R, B):
    if R % 2 == 1 or (R == 0 and B % 2 == 1):
        return None
    if B == 0:
        return all_red(R)
    if R == 0:
        return all_blue(B)
    return mixed(R, B)


def self_test():
    import random
    for R in range(0, 13):
        for B in range(0, 13):
            if R + B < 2:
                continue
            ans = construct(R, B)
            if ans is None:
                continue
            validate(R, B, ans)
    rng = random.Random(12345)
    for _ in range(300):
        R = rng.randrange(0, 2000)
        B = rng.randrange(0, 2000)
        if R + B < 2:
            continue
        ans = construct(R, B)
        if ans is None:
            continue
        validate(R, B, ans)
    for (R, B) in [(2, 199999), (199998, 3), (100000, 100000),
                   (2, 1), (2, 99999), (99998, 99999), (4, 3),
                   (199998, 1), (6, 5), (8, 1), (2, 5), (200000, 0),
                   (0, 200000), (0, 2), (2, 0)]:
        if R + B < 2:
            continue
        ans = construct(R, B)
        if ans is not None:
            validate(R, B, ans)


def solve():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    out_lines = []
    idx = 1
    for _ in range(t):
        R = int(data[idx]); B = int(data[idx + 1]); idx += 2
        ans = construct(R, B)
        if ans is None:
            out_lines.append("No")
        else:
            out_lines.append("Yes")
            for (p, r, c) in ans:
                out_lines.append(f"{p} {r} {c}")
    sys.stdout.write("\n".join(out_lines) + "\n")


