def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))

    def feasible(k):
        # Pair the k smallest (tops) with the k largest (bottoms), aligned.
        # Feasible iff every smallest top fits on the corresponding largest bottom.
        base = n - k
        for i in range(k):
            if a[i] * 2 > a[base + i]:
                return False
        return True

    lo, hi = 0, n // 2
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    sys.stdout.write(str(lo) + "\n")

main()

import sys


def solve():
    data = sys.stdin.buffer.read().split()
    K = int(data[0])
    S = bytes(data[1])
    T = bytes(data[2])
    N, M = len(S), len(T)

    out = sys.stdout.write

    if abs(N - M) > K:
        out("No\n")
        return

    def lce(x, y):
        # Longest common prefix length of S[x:] and T[y:] via binary search
        # on bytes slices (C-speed memcpy + memcmp).
        lo = 0
        hi = min(N - x, M - y)
        while lo < hi:
            mid = (lo + hi + 1) >> 1
            if S[x:x + mid] == T[y:y + mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    # Myers O(ND) greedy furthest-reaching algorithm, capped at d = K.
    # V[k] = furthest x reachable on diagonal k (y = x - k) with d edits.
    NEG = -10 ** 18

    # d = 0: single snake along diagonal 0.
    x = lce(0, 0)
    if x >= N and x >= M:  # y = x - 0 = x, so this means (N, M) reached
        out("Yes\n")
        return
    V = {0: x}

    for d in range(1, K + 1):
        newV = {}
        get = V.get
        for k in range(-d, d + 1, 2):
            # Predecessors: diagonal k+1 via insertion (x unchanged),
            # diagonal k-1 via deletion (x + 1).
            if k == -d:
                x = get(k + 1, NEG)
            elif k == d:
                x = get(k - 1, NEG) + 1
            else:
                a = get(k - 1, NEG) + 1
                b = get(k + 1, NEG)
                x = a if a > b else b
            if x < 0:
                x = 0
            elif x > N:
                x = N
            y = x - k
            if 0 <= y <= M:
                if x < N and y < M:
                    x += lce(x, y)
                newV[k] = x
                if x >= N and y >= M:
                    out("Yes\n")
                    return
            else:
                newV[k] = NEG  # off-grid diagonal; keep it unusable
        V = newV

    out("No\n")


solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def flipsNeeded(L: int) -> int:
            """Minimum flips so that every run of identical chars has length <= L."""
            if L == 1:
                # Resulting string must alternate; only two possible targets.
                # Pattern A: s[i] should be '0' if i even else '1'
                # Pattern B: the opposite. Mismatches to A and B sum to n.
                mism_a = 0
                for i, ch in enumerate(s):
                    expected = '0' if i % 2 == 0 else '1'
                    if ch != expected:
                        mism_a += 1
                return min(mism_a, n - mism_a)

            # L >= 2: handle each maximal run independently.
            # A run of length `run` needs floor(run / (L+1)) flips, and for
            # L >= 2 we can always place flips away from run boundaries so the
            # flipped chars never merge with neighboring runs.
            total = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                run = j - i
                total += run // (L + 1)
                i = j
            return total

        # Binary search the smallest feasible L in [1, n].
        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if flipsNeeded(mid) <= numOps:
                hi = mid
            else:
                lo = mid + 1
        return lo

import sys

def main():
    sys.setrecursionlimit(1 << 25)
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    A = [int(x) for x in data[1:1 + n]]

    def cross(X, Y):
        # sum over all (i, j) of f(X[i] + Y[j])
        if not X or not Y:
            return 0
        Xe, Xo, Ye, Yo = [], [], [], []
        for x in X:
            if x & 1:
                Xo.append(x)
            else:
                Xe.append(x)
        for y in Y:
            if y & 1:
                Yo.append(y)
            else:
                Ye.append(y)
        res = 0
        # mixed parity: sum is odd, f = x + y
        if Xe and Yo:
            res += len(Xe) * sum(Yo) + sum(Xe) * len(Yo)
        if Xo and Ye:
            res += len(Xo) * sum(Ye) + sum(Xo) * len(Ye)
        # both even: f(x+y) = f(x/2 + y/2)
        if Xe and Ye:
            res += cross([x >> 1 for x in Xe], [y >> 1 for y in Ye])
        # both odd: f(x+y) = f((x+1)/2 + (y-1)/2)
        if Xo and Yo:
            res += cross([(x + 1) >> 1 for x in Xo], [(y - 1) >> 1 for y in Yo])
        return res

    def self_solve(A):
        # sum over i <= j of f(A[i] + A[j])
        if not A:
            return 0
        E, O = [], []
        for a in A:
            if a & 1:
                O.append(a)
            else:
                E.append(a)
        res = 0
        # mixed parity pairs: f = e + o
        if E and O:
            res += len(E) * sum(O) + sum(E) * len(O)
        # even-even pairs
        if E:
            res += self_solve([e >> 1 for e in E])
        # odd-odd pairs: (B(U,V) + sum(O)) // 2
        if O:
            U = [(o + 1) >> 1 for o in O]
            V = [(o - 1) >> 1 for o in O]
            res += (cross(U, V) + sum(O)) // 2
        return res

    print(self_solve(A))

main()

from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold

        # DSU over values 1..T
        parent = list(range(T + 1))
        rank = [0] * (T + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        present = [False] * (T + 1)
        big = 0  # values > threshold: always isolated
        for v in nums:
            if v > T:
                big += 1
            else:
                present[v] = True

        # divisors[L] = list of present values that divide L
        # built by iterating multiples of each present value
        divisors = [[] for _ in range(T + 1)]
        for v in range(1, T + 1):
            if present[v]:
                for m in range(v, T + 1, v):
                    divisors[m].append(v)

        # For each L, all present divisors of L pairwise have lcm dividing L,
        # hence lcm <= T, so they are all mutually connected.
        for L in range(1, T + 1):
            lst = divisors[L]
            if len(lst) >= 2:
                first = lst[0]
                for other in lst[1:]:
                    union(first, other)

        roots = set()
        for v in range(1, T + 1):
            if present[v]:
                roots.add(find(v))

        return len(roots) + big
